// Parse and organize all form data
const formData = $input.first().json;

// Parse network devices JSON
let networkDevices = [];
try {
  networkDevices = JSON.parse(formData['Network Devices (JSON)'] || '[]');
} catch (e) {
  networkDevices = { error: 'Invalid JSON', raw: formData['Network Devices (JSON)'] };
}

// Parse multi-select fields (come as comma-separated strings)
const parseMultiSelect = (field) => {
  if (!field) return [];
  if (Array.isArray(field)) return field;
  return field.split(',').map(s => s.trim());
};

const clientData = {
  projectName: formData['Client/Project Name']?.toLowerCase().replace(/[^a-z0-9]/g, '-') || 'unnamed-project',
  companyName: formData['Company Name'] || 'Unknown Company',
  contactEmail: formData['Client Contact Email'] || '',
  logoUrl: formData['Company Logo URL'] || '',
  repoName: `${formData['Client/Project Name']?.toLowerCase().replace(/[^a-z0-9]/g, '-')}-network-automation`
};

const infrastructure = {
  networkDevices: networkDevices,
  sourceOfTruth: formData['Source of Truth'] || 'None',
  iacTool: formData['Infrastructure as Code Tool'] || 'None',
  configMgmtTool: formData['Configuration Management Tool'] || 'None',
  vendors: parseMultiSelect(formData['Network Vendors']),
  cloudEnvironments: parseMultiSelect(formData['Cloud Environments'])
};

const documentation = {
  formats: parseMultiSelect(formData['Documentation Formats']),
  boxFolderId: formData['Box Folder ID (for documentation)'] || '',
  miroBoardId: formData['Miro Board ID (if using Miro)'] || ''
};

const delivery = {
  target: formData['Delivery Target'] || 'GitHub',
  orgName: formData['Git Organization/Group Name'] || 'default-org'
};

const notifications = {
  preference: formData['Notification Preference'] || 'None',
  slackChannel: formData['Slack Channel (if using Slack)'] || '',
  email: formData['Notification Email (if using Email)'] || formData['Client Contact Email'] || ''
};

return {
  json: {
    clientData,
    infrastructure,
    documentation,
    delivery,
    notifications,
    generatedAt: new Date().toISOString()
  }
};

// Generate comprehensive documentation content
const data = $input.first().json;
const { clientData, infrastructure, documentation } = data;

// Generate Network Inventory Documentation
const generateNetworkInventory = () => {
  let md = `# Network Inventory Documentation\n\n`;
  md += `**Client:** ${clientData.companyName}\n`;
  md += `**Project:** ${clientData.projectName}\n`;
  md += `**Generated:** ${data.generatedAt}\n\n`;

  md += `## Executive Summary\n\n`;
  md += `This document provides a comprehensive inventory of network infrastructure for ${clientData.companyName}.\n\n`;

  md += `## Network Devices\n\n`;
  md += `| Type | Vendor | Model | Platform | Quantity | IP Range | Site | Role |\n`;
  md += `|------|--------|-------|----------|----------|----------|------|------|\n`;

  if (Array.isArray(infrastructure.networkDevices)) {
    infrastructure.networkDevices.forEach(device => {
      md += `| ${device.type || '-'} | ${device.vendor || '-'} | ${device.model || '-'} | ${device.platform || '-'} | ${device.quantity || '-'} | ${device.ip_range || '-'} | ${device.site || '-'} | ${device.role || '-'} |\n`;
    });
  }

  md += `\n## Vendor Summary\n\n`;
  infrastructure.vendors.forEach(vendor => {
    md += `- ${vendor}\n`;
  });

  md += `\n## Cloud Environments\n\n`;
  infrastructure.cloudEnvironments.forEach(env => {
    md += `- ${env}\n`;
  });

  md += `\n## Automation Stack\n\n`;
  md += `- **Source of Truth:** ${infrastructure.sourceOfTruth}\n`;
  md += `- **Infrastructure as Code:** ${infrastructure.iacTool}\n`;
  md += `- **Configuration Management:** ${infrastructure.configMgmtTool}\n`;

  return md;
};

// Generate Architecture Documentation
const generateArchitectureDoc = () => {
  let md = `# Network Automation Architecture\n\n`;
  md += `## Overview\n\n`;
  md += `This document describes the automation architecture for ${clientData.companyName}.\n\n`;

  md += `## Components\n\n`;
  md += `### Source of Truth\n`;
  if (infrastructure.sourceOfTruth !== 'None') {
    md += `- **Platform:** ${infrastructure.sourceOfTruth}\n`;
    md += `- **Purpose:** Central repository for network device inventory, IP addressing, and configuration data\n\n`;
  } else {
    md += `- No dedicated source of truth configured\n\n`;
  }

  md += `### Infrastructure as Code\n`;
  if (infrastructure.iacTool !== 'None') {
    md += `- **Tool:** ${infrastructure.iacTool}\n`;
    md += `- **Purpose:** Declarative infrastructure provisioning and management\n`;
    if (infrastructure.cloudEnvironments.includes('AWS')) md += `- AWS Provider configured\n`;
    if (infrastructure.cloudEnvironments.includes('Azure')) md += `- Azure Provider configured\n`;
    if (infrastructure.cloudEnvironments.includes('GCP')) md += `- GCP Provider configured\n`;
    md += `\n`;
  } else {
    md += `- No IaC tool configured\n\n`;
  }

  md += `### Configuration Management\n`;
  if (infrastructure.configMgmtTool !== 'None') {
    md += `- **Tool:** ${infrastructure.configMgmtTool}\n`;
    md += `- **Purpose:** Network device configuration deployment and compliance\n\n`;
  } else {
    md += `- No configuration management tool configured\n\n`;
  }

  md += `## Supported Platforms\n\n`;
  infrastructure.vendors.forEach(vendor => {
    md += `### ${vendor}\n`;
    md += `- Configuration templates included\n`;
    md += `- Backup and restore playbooks\n`;
    md += `- Compliance validation rules\n\n`;
  });

  return md;
};

// Generate Runbook Documentation
const generateRunbook = () => {
  let md = `# Operations Runbook\n\n`;
  md += `## ${clientData.companyName} - Network Operations\n\n`;

  md += `## Quick Reference\n\n`;
  md += `| Task | Command | Description |\n`;
  md += `|------|---------|-------------|\n`;

  if (infrastructure.configMgmtTool.includes('Ansible')) {
    md += `| Deploy Config | \`ansible-playbook deploy.yml\` | Deploy configurations to devices |\n`;
    md += `| Backup Configs | \`ansible-playbook backup.yml\` | Backup all device configurations |\n`;
    md += `| Compliance Check | \`ansible-playbook compliance.yml\` | Run compliance validation |\n`;
  }

  if (infrastructure.configMgmtTool.includes('Nornir')) {
    md += `| Deploy Config | \`python deploy.py\` | Deploy configurations via Nornir |\n`;
    md += `| Backup Configs | \`python backup.py\` | Backup all device configurations |\n`;
    md += `| Inventory Report | \`python inventory.py\` | Generate inventory report |\n`;
  }

  if (infrastructure.iacTool === 'Terraform') {
    md += `| Plan Changes | \`terraform plan\` | Preview infrastructure changes |\n`;
    md += `| Apply Changes | \`terraform apply\` | Apply infrastructure changes |\n`;
    md += `| Destroy | \`terraform destroy\` | Destroy managed infrastructure |\n`;
  }

  if (infrastructure.iacTool === 'Pulumi') {
    md += `| Preview Changes | \`pulumi preview\` | Preview infrastructure changes |\n`;
    md += `| Deploy | \`pulumi up\` | Deploy infrastructure changes |\n`;
    md += `| Destroy | \`pulumi destroy\` | Destroy managed infrastructure |\n`;
  }

  md += `\n## Troubleshooting\n\n`;
  md += `### Common Issues\n\n`;
  md += `1. **Connection Timeout**\n`;
  md += `   - Verify network connectivity to device\n`;
  md += `   - Check firewall rules\n`;
  md += `   - Validate credentials\n\n`;
  md += `2. **Authentication Failed**\n`;
  md += `   - Verify credentials in vault/secrets manager\n`;
  md += `   - Check user permissions on device\n\n`;
  md += `3. **Configuration Conflict**\n`;
  md += `   - Review pending changes\n`;
  md += `   - Check for manual changes on device\n`;

  return md;
};

const networkInventory = generateNetworkInventory();
const architectureDoc = generateArchitectureDoc();
const runbook = generateRunbook();

return {
  json: {
    ...data,
    docs: {
      networkInventory,
      architectureDoc,
      runbook,
      formats: documentation.formats
    }
  }
};

