// Generate Infrastructure as Code files
const data = $input.first().json;
const { clientData, infrastructure, files } = data;

const iacTool = infrastructure.iacTool;
const cloudEnvs = infrastructure.cloudEnvironments;

if (iacTool === 'Terraform') {
  // Main Terraform configuration
  let mainTf = `# Terraform Configuration for ${clientData.companyName}\n\nterraform {\n  required_version = ">= 1.0.0"\n  required_providers {\n`;

  if (cloudEnvs.includes('AWS')) {
    mainTf += `    aws = {\n      source  = "hashicorp/aws"\n      version = "~> 5.0"\n    }\n`;
  }
  if (cloudEnvs.includes('Azure')) {
    mainTf += `    azurerm = {\n      source  = "hashicorp/azurerm"\n      version = "~> 3.0"\n    }\n`;
  }
  if (cloudEnvs.includes('GCP')) {
    mainTf += `    google = {\n      source  = "hashicorp/google"\n      version = "~> 5.0"\n    }\n`;
  }

  mainTf += `  }\n}\n`;

  if (cloudEnvs.includes('AWS')) {
    mainTf += `\nprovider "aws" {\n  region = var.aws_region\n}\n`;
  }
  if (cloudEnvs.includes('Azure')) {
    mainTf += `\nprovider "azurerm" {\n  features {}\n}\n`;
  }
  if (cloudEnvs.includes('GCP')) {
    mainTf += `\nprovider "google" {\n  project = var.gcp_project\n  region  = var.gcp_region\n}\n`;
  }

  files.push({ path: 'iac/terraform/main.tf', content: mainTf });

  // Variables
  let variablesTf = `# Variables for ${clientData.companyName}\n\n`;
  if (cloudEnvs.includes('AWS')) {
    variablesTf += `variable "aws_region" {\n  description = "AWS region"\n  type        = string\n  default     = "us-east-1"\n}\n\n`;
  }
  if (cloudEnvs.includes('Azure')) {
    variablesTf += `variable "azure_location" {\n  description = "Azure location"\n  type        = string\n  default     = "eastus"\n}\n\n`;
  }
  if (cloudEnvs.includes('GCP')) {
    variablesTf += `variable "gcp_project" {\n  description = "GCP project ID"\n  type        = string\n}\n\nvariable "gcp_region" {\n  description = "GCP region"\n  type        = string\n  default     = "us-central1"\n}\n\n`;
  }

  files.push({ path: 'iac/terraform/variables.tf', content: variablesTf });

  // Outputs
  const outputsTf = `# Outputs for ${clientData.companyName}\n\n# Add outputs as needed\n`;
  files.push({ path: 'iac/terraform/outputs.tf', content: outputsTf });

  // Terraform README
  const tfReadme = `# Terraform Infrastructure\n\n## Usage\n\n\`\`\`bash\ncd iac/terraform\nterraform init\nterraform plan\nterraform apply\n\`\`\`\n`;
  files.push({ path: 'iac/terraform/README.md', content: tfReadme });

} else if (iacTool === 'Pulumi') {
  // Pulumi configuration
  const pulumiYaml = `name: ${clientData.repoName}\nruntime: python\ndescription: Network infrastructure for ${clientData.companyName}\n`;
  files.push({ path: 'iac/pulumi/Pulumi.yaml', content: pulumiYaml });

  // Main Pulumi program
  let mainPy = `"""Network infrastructure for ${clientData.companyName}"""\nimport pulumi\n`;

  if (cloudEnvs.includes('AWS')) {
    mainPy += `import pulumi_aws as aws\n`;
  }
  if (cloudEnvs.includes('Azure')) {
    mainPy += `import pulumi_azure_native as azure\n`;
  }
  if (cloudEnvs.includes('GCP')) {
    mainPy += `import pulumi_gcp as gcp\n`;
  }

  mainPy += `\n# Configuration\nconfig = pulumi.Config()\n\n# Add your infrastructure resources here\n`;

  files.push({ path: 'iac/pulumi/__main__.py', content: mainPy });

  // Pulumi requirements
  let pulumiReqs = `pulumi>=3.0.0\n`;
  if (cloudEnvs.includes('AWS')) pulumiReqs += `pulumi-aws>=6.0.0\n`;
  if (cloudEnvs.includes('Azure')) pulumiReqs += `pulumi-azure-native>=2.0.0\n`;
  if (cloudEnvs.includes('GCP')) pulumiReqs += `pulumi-gcp>=7.0.0\n`;

  files.push({ path: 'iac/pulumi/requirements.txt', content: pulumiReqs });

  // Pulumi README
  const pulumiReadme = `# Pulumi Infrastructure\n\n## Usage\n\n\`\`\`bash\ncd iac/pulumi\npulumi login\npulumi stack init dev\npulumi up\n\`\`\`\n`;
  files.push({ path: 'iac/pulumi/README.md', content: pulumiReadme });
}

// Add placeholder if no IaC
if (iacTool === 'None') {
  files.push({ 
    path: 'iac/README.md', 
    content: `# Infrastructure as Code\n\nNo IaC tool configured for this project.\n` 
  });
}

return {
  json: {
    ...data,
    files
  }
};

// Generate Configuration Management files
const data = $input.first().json;
const { clientData, infrastructure, files } = data;

const configMgmtTool = infrastructure.configMgmtTool;
const vendors = infrastructure.vendors;
const devices = infrastructure.networkDevices;

// Helper to get platform type from vendor
const getPlatform = (vendor) => {
  const mapping = {
    'Cisco IOS': 'cisco_ios',
    'Cisco IOS-XE': 'cisco_xe',
    'Cisco NX-OS': 'cisco_nxos',
    'Juniper Junos': 'juniper_junos',
    'Arista EOS': 'arista_eos',
    'Palo Alto': 'paloalto_panos',
    'Fortinet': 'fortinet',
    'Cisco ASA/Firepower': 'cisco_asa',
    'Check Point': 'checkpoint',
    'F5 BIG-IP': 'f5_bigip',
    'Citrix NetScaler': 'citrix_netscaler',
    'HAProxy': 'linux'
  };
  return mapping[vendor] || 'unknown';
};

if (configMgmtTool.includes('Ansible')) {
  // Ansible inventory
  let inventory = `# Ansible Inventory for ${clientData.companyName}
all:
  children:
`;

  // Group by vendor
  const vendorGroups = {};
  vendors.forEach(v => {
    const platform = getPlatform(v);
    vendorGroups[platform] = vendorGroups[platform] || [];
  });

  Object.keys(vendorGroups).forEach(platform => {
    inventory += `    ${platform}:
      hosts:
`;
    inventory += `        # Add hosts here
`;
  });

  inventory += `  vars:
    ansible_user: "{{ lookup('env', 'NETWORK_USERNAME') }}"
    ansible_password: "{{ lookup('env', 'NETWORK_PASSWORD') }}"
`;

  files.push({ path: 'config-management/ansible/inventory/hosts.yml', content: inventory });

  // Ansible.cfg
  const ansibleCfg = `[defaults]
inventory = inventory/hosts.yml
host_key_checking = False
retry_files_enabled = False
gathering = smart
fact_caching = jsonfile
fact_caching_connection = /tmp/ansible_facts
fact_caching_timeout = 86400

[persistent_connection]
connect_timeout = 30
command_timeout = 30
`;
  files.push({ path: 'config-management/ansible/ansible.cfg', content: ansibleCfg });

  // Deploy playbook
  const deployPlaybook = `---
# Deploy configurations to network devices
- name: Deploy Network Configurations
  hosts: all
  gather_facts: no

  tasks:
    - name: Load device-specific variables
      include_vars:
        file: "host_vars/{{ inventory_hostname }}.yml"
      ignore_errors: yes

    - name: Deploy configuration
      ansible.netcommon.cli_config:
        config: "{{ lookup('template', 'templates/{{ ansible_network_os }}/base.j2') }}"
      when: config_deploy | default(true)
`;
  files.push({ path: 'config-management/ansible/playbooks/deploy.yml', content: deployPlaybook });

  // Backup playbook
  const backupPlaybook = `---
# Backup configurations from network devices
- name: Backup Network Configurations
  hosts: all
  gather_facts: no

  tasks:
    - name: Backup running configuration
      ansible.netcommon.cli_command:
        command: show running-config
      register: config_output

    - name: Save configuration to file
      copy:
        content: "{{ config_output.stdout }}"
        dest: "backups/{{ inventory_hostname }}_{{ ansible_date_time.date }}.cfg"
      delegate_to: localhost
`;
  files.push({ path: 'config-management/ansible/playbooks/backup.yml', content: backupPlaybook });

  // Compliance playbook
  const compliancePlaybook = `---
# Run compliance checks on network devices
- name: Network Compliance Validation
  hosts: all
  gather_facts: no

  tasks:
    - name: Check NTP configuration
      ansible.netcommon.cli_command:
        command: show ntp status
      register: ntp_status
      ignore_errors: yes

    - name: Validate NTP is configured
      assert:
        that:
          - ntp_status.stdout is defined
        fail_msg: "NTP is not configured on {{ inventory_hostname }}"
        success_msg: "NTP is properly configured"
`;
  files.push({ path: 'config-management/ansible/playbooks/compliance.yml', content: compliancePlaybook });

  // Create templates for each vendor
  vendors.forEach(vendor => {
    const platform = getPlatform(vendor);
    const template = `{# Base configuration template for ${vendor} #}
{# Variables: hostname, domain_name, ntp_servers, dns_servers #}

! Hostname
hostname {{ hostname }}

! Domain
ip domain-name {{ domain_name | default('local') }}

! NTP
{% for ntp in ntp_servers | default(['pool.ntp.org']) %}
ntp server {{ ntp }}
{% endfor %}

! DNS
{% for dns in dns_servers | default(['8.8.8.8', '8.8.4.4']) %}
ip name-server {{ dns }}
{% endfor %}
`;
    files.push({ path: `config-management/ansible/templates/${platform}/base.j2`, content: template });
  });

  // Ansible README
  const ansibleReadme = `# Ansible Configuration Management

## Structure

\`\`\`
ansible/
├── ansible.cfg
├── inventory/
│   └── hosts.yml
├── playbooks/
│   ├── deploy.yml
│   ├── backup.yml
│   └── compliance.yml
├── templates/
│   └── <platform>/
└── host_vars/
\`\`\`

## Usage

\`\`\`bash
# Deploy configurations
ansible-playbook playbooks/deploy.yml

# Backup configurations
ansible-playbook playbooks/backup.yml

# Run compliance checks
ansible-playbook playbooks/compliance.yml
\`\`\`
`;
  files.push({ path: 'config-management/ansible/README.md', content: ansibleReadme });
}

if (configMgmtTool.includes('Nornir')) {
  // Nornir config
  const nornirConfig = `---
inventory:
  plugin: SimpleInventory
  options:
    host_file: "inventory/hosts.yml"
    group_file: "inventory/groups.yml"
    defaults_file: "inventory/defaults.yml"

runner:
  plugin: threaded
  options:
    num_workers: 10
`;
  files.push({ path: 'config-management/nornir/config.yml', content: nornirConfig });

  // Nornir hosts inventory
  const nornirHosts = `---
# Add hosts here
# Example:
# router1:
#   hostname: 192.168.1.1
#   groups:
#     - cisco_ios
`;
  files.push({ path: 'config-management/nornir/inventory/hosts.yml', content: nornirHosts });

  // Nornir groups
  let nornirGroups = `---
`;
  vendors.forEach(vendor => {
    const platform = getPlatform(vendor);
    nornirGroups += `${platform}:
  platform: ${platform}
  connection_options:
    netmiko:
      platform: ${platform}

`;
  });
  files.push({ path: 'config-management/nornir/inventory/groups.yml', content: nornirGroups });

  // Nornir defaults
  const nornirDefaults = `---
username: "{{ env 'NETWORK_USERNAME' }}"
