`;
  files.push({ path: 'config-management/nornir/inventory/defaults.yml', content: nornirDefaults });

  // Deploy script
  const deployPy = `#!/usr/bin/env python3
"""Deploy configurations to network devices using Nornir."""
from nornir import InitNornir
from nornir_netmiko import netmiko_send_config
from nornir_utils.plugins.functions import print_result
from nornir_jinja2.plugins.tasks import template_file
import os

def deploy_config(task):
    """Deploy configuration to a device."""
    # Render template
    r = task.run(
        task=template_file,
        template="base.j2",
        path=f"templates/{task.host.platform}/"
    )

    # Deploy configuration
    task.run(
        task=netmiko_send_config,
        config_commands=r.result.splitlines()
    )

def main():
    nr = InitNornir(config_file="config.yml")
    result = nr.run(task=deploy_config)
    print_result(result)

if __name__ == "__main__":
    main()
`;
  files.push({ path: 'config-management/nornir/deploy.py', content: deployPy });

  // Backup script
  const backupPy = `#!/usr/bin/env python3
"""Backup configurations from network devices using Nornir."""
from nornir import InitNornir
from nornir_netmiko import netmiko_send_command
from nornir_utils.plugins.functions import print_result
from datetime import datetime
import os

def backup_config(task):
    """Backup configuration from a device."""
    r = task.run(
        task=netmiko_send_command,
        command_string="show running-config"
    )

    # Save to file
    os.makedirs("backups", exist_ok=True)
    filename = f"backups/{task.host.name}_{datetime.now().strftime('%Y%m%d')}.cfg"
    with open(filename, "w") as f:
        f.write(r.result)

def main():
    nr = InitNornir(config_file="config.yml")
    result = nr.run(task=backup_config)
    print_result(result)

if __name__ == "__main__":
    main()
`;
  files.push({ path: 'config-management/nornir/backup.py', content: backupPy });

  // Nornir README
  const nornirReadme = `# Nornir Configuration Management

## Structure

